cd /home/runner/hub-work/.zen-agent/restored && python3 -c "
import json,glob
found=set()
for f in glob.glob('saved-*.json'):
    try: d=json.load(open(f))
    except Exception: continue
    def walk(o):
        if isinstance(o,dict):
            if 'directory' in o and isinstance(o.get('directory'),str) and 'comic2film' in o['directory']:
                found.add((o.get('id'),o.get('directory'),o.get('title')))
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(d)
print('sessions in comic2film dir:', len(found))
for x in list(found)[:10]: print(x)
"

