   ok(/if \(e\.noRetry\) throw e;/.test(ai), 'ai.js: разобранный, но негодный ответ не ретраится');
   ok(!/String\(answer\)/.test(chat) && /answerText\(answer, 'ИИ'\)/.test(chat),
