/* Вытащить валидный JSON из ответа (иногда рядом текст) */
export function parseJsonLoose(s) {
  if (!s) return null;
  s = s.trim();
  try { return JSON.parse(s); } catch (e) { /* дальше ищем блок */ }
  const obj = s.match(/\{[\s\S]*\}/);
  if (obj) { try { return JSON.parse(obj[0]); } catch (e) {} }
  const arr = s.match(/\[[\s\S]*\]/);
  if (arr) { try { return JSON.parse(arr[0]); } catch (e) {} }
  return null;
}

/* Проверка: надо ли подождать из-за лимитов (429).
 * Счётчик ожиданий ведёт каждый вызов, а не этот хелпер. */

/** chat — единая точка вызова для любого провайдера из каталога.
 * settings: {ai:'pollinations'|'openrouter'|'openai'|'anthropic'|'gemini'|..., key, aiurl, aimodel, aiGap}
 * messages: [{role, content}] — content может быть строкой или массивом частей.
 * opts: {json:bool, minGap:ms}
 */
export async function chat(settings, messages, opts = {}) {
  const p = provider(settings.ai);
  const model = settings.aimodel || (p.models[0] ? p.models[0].id : 'openai');
  settings = { ...settings, aimodel: model };
  if (p.gemini) return chatGemini(settings, messages, opts);
  if (p.anthropic) return chatAnthropic(settings, messages, opts);
  let endpoint = settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint;
  const key = settings.key || '';
  if (modelDemoKeyless(settings.ai, model) && !key) {
    const relay = (settings.zenRelay || '').trim().replace(/\/+$/, '');
    if (!relay) {
      throw new Error(
        `«${model}» — free tier OpenCode Zen без ключа. Браузер не может напрямую ` +
        'отправить identity-заголовки opencode CLI (User-Agent, x-opencode-*), поэтому ' +
        'такие модели работают через мини-релей: команда «node relay/zen-relay.mjs», ' +
        'её URL задайте в настройках («URL Zen-релея»), либо добавьте ключ Zen.'
      );
    }
    endpoint = relay + '/v1/chat/completions';
  }
  if (!endpoint) throw new Error('Свой провайдер: не задан адрес OpenAI-совместимого API');
  return openAICompat({
    name: (p.name || settings.ai).split(' ·')[0],
    endpoint,
    headers: p.headers || {},
    key,
    model,
    messages: messagesWithImages(messages, opts.images),
    json: opts.json,
    gap: opts.minGap ?? settings.aiGap ?? 2500,
    signal: opts.signal,
  });
}

/* Превращает массив dataURL-картинок в OpenAI-совместимые parts */
function messagesWithImages(messages, images) {
  if (!images || !images.length) return messages;
  const img = images[0];
  const body = { type: 'image_url', image_url: { url: img && (img.dataURL || img) } };
  return messages.map(m => {
    if (m.role !== 'user') return m;
    if (typeof m.content === 'string') m.content = [{ type: 'text', text: m.content }];
    if (Array.isArray(m.content)) m.content = [...m.content, body];
    return m;
  });
}

/* Отправка картинки vision-провайдеру поверх текстового контекста */
export async function chatWithImage(settings, messages, imageDataURL) {
  settings = { ...settings, aimodel: settings.aimodel || provider(settings.ai).models[0]?.id || 'openai' };
  const p = provider(settings.ai);
  if (!p.vision) throw new Error('«' + (p.name || settings.ai) + '» не умеет смотреть изображения (выберите vision-провайдер)');
  const text = messages.filter(m => m.role !== 'system').map(m => (m.role === 'user' ? 'Пользователь: ' : 'ИИ: ') + textOf(m.content)).join('\n');
  if (p.gemini) return chatGeminiVision(settings, imageDataURL, text);
  if (p.anthropic) return chatAnthropicVision(settings, imageDataURL, text);
  return openAICompat({
    name: (p.name || settings.ai).split(' ·')[0],
    endpoint: settings.ai === 'custom' ? (settings.aiurl || '') : p.endpoint,
    headers: p.headers || {},
    key: settings.key || '',
    model: settings.aimodel,
    messages: [{ role: 'user', content: [{ type: 'text', text }, { type: 'image_url', image_url: { url: imageDataURL } }] }],
  });
}

/* Универсальный вызов OpenAI-совместимых API (Pollinations/OpenRouter/OpenAI/
 * Groq/DeepSeek/Mistral/Together/xAI/Perplexity/Cerebras/custom) с ретраями
 * при 429/5xx и парсингом JSON-ответа. */
async function openAICompat({ name, endpoint, headers = {}, key = '', model, messages, json = false, gap = 2500, signal }) {
  const hd = { 'Content-Type': 'application/json', ...(key ? { Authorization: 'Bearer ' + key } : {}), ...headers };
  let attempt = 0, waits = 0;
  let wantJsonMode = json; // не все провайдеры понимают response_format
  while (true) {
    const body = { model, messages, temperature: temperatureFor(model, wantJsonMode) };
    if (body.temperature === undefined) delete body.temperature;
    if (wantJsonMode) body.response_format = { type: 'json_object' };
    try {
      const r = await fetch(endpoint, { method: 'POST', headers: hd, body: JSON.stringify(body), signal });
      if (r.status === 429 && waits < 3) { waits++; await sleep(5000 * waits); continue; }
      if (!r.ok) {
        const t = await r.text().catch(() => '');
        // провайдер не умеет response_format — пробуем без него, это не ошибка запроса
        if (wantJsonMode && r.status === 400 && /response_format|json_object/i.test(t)) {
          wantJsonMode = false; attempt = 0; continue;
        }
        const err = new Error(`${name} ${r.status}: ${t.slice(0, 180)}`);
        err.status = r.status;
        throw err;
      }
      const j = await r.json();
      const msg = (j.choices && j.choices[0] && j.choices[0].message) || {};
      // keyless-модели zen — агенты: на «создай файл» они отвечают вызовом
      // инструмента, а не текстом. Раньше content молча становился пустым (или
      // null → «null» в пузыре), и диалог уезжал в «nullnullnull…».
      if (Array.isArray(msg.tool_calls) && msg.tool_calls.length) {
        throw toolCallsError(name + ' ' + model, msg.tool_calls);
      }
      const raw = msg.content;
      if (wantJsonMode) {
        const parsed = parseJsonLoose(typeof raw === 'string' ? raw : JSON.stringify(raw));
        if (parsed) return parsed;
      }
      return answerText(raw, name + ' ' + model);
    } catch (e) {
      if (e.name === 'AbortError') throw e;
      // 4xx (кроме 429, который обработан выше) — запрос неверный, повтор не поможет
      if (e.status >= 400 && e.status < 500) throw e;
      if (e.noRetry) throw e;   // ответ разобран, но годный текст из него не получить
      if (attempt >= 3) throw e;
      await sleep(gap * (attempt + 1));
      attempt++;
    }
  }
}

/* reasoning-модели (o1/o3/o4, gpt-5*, codex) принимают только temperature=1,
 * любое другое значение даёт 400. Для них поле просто не отправляется. */
const REASONING_MODELS = /^(o[1-9]\d*(\.\d+)?(-|$)|gpt-5|codex)/i;

function temperatureFor(model, json) {
  if (json) return 0.1;
  if (REASONING_MODELS.test(String(model || ''))) return undefined;
  return 0.5;
}

export { temperatureFor, REASONING_MODELS };

/* Текст из parts OpenAI-совместимого формата (после подстановки картинок). */
export function textOf(content) {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content.map(p => (p && typeof p.text === 'string' ? p.text : (p && p.type === 'image_url' ? '' : ''))).filter(Boolean).join(' ');
  }
  return content == null ? '' : String(content);
}

/* Имена инструментов из ответа провайдера (OpenAI / Gemini / Anthropic). */
export function toolNames(calls) {
  const out = [];
  for (const c of Array.isArray(calls) ? calls : []) {
    const n = (c && c.function && c.function.name) || (c && c.name) ||
      (c && c.functionCall && c.functionCall.name) || (c && c.type === 'tool_use' && c.name);
    if (n) out.push(String(n));
  }
  return [...new Set(out)];
}

/* Модель вместо ответа вызвала инструмент. У VoiceComic в чате инструментов
 * нет, и раньше такой ответ молча превращался в пустой content: модель обещала
 * «сейчас посмотрю папку», ничего не происходило, а следующим ходом она
 * сыпала «nullnullnull…». Теперь это внятная ошибка с именами инструментов. */
export function toolCallsError(label, calls) {
  const names = toolNames(calls);
  const e = new Error(
    `«${label}» вместо ответа вызвал${names.length === 1 ? 'а' : 'и'} инструмент` +
    `${names.length ? 'ы: ' + names.join(', ') : ''}. В чате VoiceComic инструментов нет — задайте вопрос текстом ` +
    '(например: «придумай 3 реплики для панели») или выберите другую модель.'
  );
  e.toolCalls = names;
  e.noRetry = true;   // повтор не поможет: модель снова позовёт инструмент
  return e;
}

/* Мусорный ответ: «nullnullnull…», «ааааааа» и прочие зацикленные повторы.
 * Модели на длинных промптах (особенно бесплатные keyless) срываются именно
 * так, и пользователь получал простыню мусора вместо ответа. */
export function sanitizeModelText(t) {
  if (typeof t !== 'string') return '';
  return t
    .replace(/(?:[ \t]*(?:null|undefined|NaN)){4,}[ \t]*/gi, ' ')
    .replace(/(.)\1{40,}/gs, '$1…')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

/** Привести ответ провайдера к тексту или объяснить, почему текста нет. */
export function answerText(raw, label) {
  if (Array.isArray(raw) && raw.some(p => p && (p.functionCall || p.tool_use || p.type === 'function_call'))) {
    throw toolCallsError(label, raw);
  }
  if (toolNames(raw).length) throw toolCallsError(label, raw);
  const text = sanitizeModelText(textOf(raw));
  if (!text) {
    const e = new Error(`«${label}» вернул${raw == null ? ' null' : ' пустой'} ответ — повторите вопрос или смените модель`);
    e.noRetry = true;
    throw e;
  }
  return text;
}

async function chatGemini(settings, messages, opts = {}) {
  const model = settings.aimodel || 'gemini-2.0-flash';
  const key = settings.key || '';
  if (!key) throw new Error('Gemini: нужен API-ключ');
  const gap = opts.minGap ?? settings.aiGap ?? 2500;
  const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;
  // system-роль Gemini не знает: раньше системный промпт уходил как ещё один
  // user-turn, и модель отвечала на него вместо вопроса.
  const sys = messages.filter(m => m.role === 'system').map(m => textOf(m.content)).join('\n\n');
  const parts = messages
    .filter(m => m.role !== 'system')
    .map(m => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: textOf(m.content) }] }));
  if (!parts.length) parts.push({ role: 'user', parts: [{ text: 'ping' }] });
  const payload = { contents: parts };
  if (sys.trim()) payload.systemInstruction = { parts: [{ text: sys }] };
  const img = opts.images && opts.images[0];
  if (img && parts.length) {
    const d = img.dataURL || img;
    const inl = d.split(';base64,');
    parts[parts.length - 1].parts.push({ inline_data: { mime_type: inl[0].split(':')[1] || 'image/jpeg', data: inl[1] } });
  }
  let attempt = 0, waits = 0;
  while (true) {
    try {
      const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), signal: opts.signal });
      if (r.status === 429 && waits < 3) { waits++; await sleep(5000 * waits); continue; }
      if (!r.ok) { const t = await r.text().catch(() => ''); const e = new Error('Gemini ' + r.status + (t ? ': ' + t.slice(0, 150) : '')); e.status = r.status; throw e; }
      const j = await r.json();
      const blocks = j.candidates?.[0]?.content?.parts || [];
      // functionCall-части — это вызов инструмента, а не ответ
      const calls = blocks.filter(p => p && p.functionCall);
      if (calls.length) throw toolCallsError('Gemini ' + model, calls);
      const out = sanitizeModelText(blocks.map(p => (p && typeof p.text === 'string' ? p.text : '')).join(''));
      if (!out && j.candidates?.[0]?.finishReason && j.candidates[0].finishReason !== 'STOP') {
        const e = new Error('Gemini ' + j.candidates[0].finishReason + (j.promptFeedback?.blockReason ? ' (' + j.promptFeedback.blockReason + ')' : ''));
        e.status = 400; throw e;
      }
      if (opts.json) { const parsed = parseJsonLoose(out); if (parsed) return parsed; }
      return out;
    } catch (e) {
      if (e.name === 'AbortError') throw e;
      if (e.status >= 400 && e.status < 500) throw e;
      if (e.noRetry) throw e;
      if (attempt >= 3) throw e;
      attempt++;
      await sleep(gap * attempt);
    }
  }
}

async function chatAnthropic(settings, messages, opts = {}) {
  const model = settings.aimodel || 'claude-sonnet-4-5';
  const key = settings.key || '';
  if (!key) throw new Error('Anthropic: нужен API-ключ');
  const welcome = provider(settings.ai);
  const endpoint = settings.ai === 'custom' ? (settings.aiurl || '') : welcome.endpoint;
  const sys = messages.filter(m => m.role === 'system').map(m => textOf(m.content)).join('\n\n');
  let bodyMsgs = messages.filter(m => m.role !== 'system').map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: textOf(m.content) }));
  if (!bodyMsgs.length) bodyMsgs = [{ role: 'user', content: 'ping' }];
  const img = opts.images && opts.images[0];
  if (img && bodyMsgs.length) {
    const d = img.dataURL || img;
    const inl = d.split(';base64,');
    const mime = inl[0].split(':')[1] || 'image/jpeg';
    const content = typeof bodyMsgs[bodyMsgs.length - 1].content === 'string'
      ? [{ type: 'text', text: bodyMsgs[bodyMsgs.length - 1].content }]
      : bodyMsgs[bodyMsgs.length - 1].content;
    content.push({ type: 'image', source: { type: 'base64', media_type: mime, data: inl[1] } });
    bodyMsgs[bodyMsgs.length - 1].content = content;
  }
  const body = { model, max_tokens: 4096, messages: bodyMsgs };
  if (sys.trim()) body.system = sys;
  const gap = opts.minGap ?? settings.aiGap ?? 2500;
  let attempt = 0, waits = 0;
  while (true) {
    try {
      const r = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify(body),
        signal: opts.signal,
      });
