function fmtSize(n) { return n > 1048576 ? (n / 1048576).toFixed(1) + ' МБ' : n > 1024 ? Math.round(n / 1024) + ' КБ' : n + ' Б'; }

/* Прочитать текстовое вложение, чтобы отправить его модели.
