Now sseFoldResponses: collect tool calls.

Events to handle:
- `response.output_item.added` with `item.type === 'function_call'` → start entry with id/name
- `response.function_call_arguments.delta` with `item_id`/`output_index` and `delta` → append arguments
- `response.output_item.done` with `item.type === 'function_call'` → final item (id, name, arguments)

Key for map: prefer `item.id` for the item (output_index also available). Let me use `item.id || o.item_id || o.output_index`.

Then build array in insertion order.

Implementation:

```js
export function sseFoldResponses(raw) {
  let content = '';
  let status = 'completed';
  let stopped = false;
  let err = null;
  let incomplete = null;
  let usage = null;
  const calls = new Map();
  const callEntry = (key, item) => {
    const k = String(key);
    let c = calls.get(k);
    if (!c) { c = { id: '', type: 'function', function: { name: '', arguments: '' } }; calls.set(k, c); }
    if (item) {
      if (item.call_id) c.id = item.call_id;
      else if (item.id) c.id = item.id;
      if (item.name && !c.function.name) c.function.name = item.name;
      if (typeof item.arguments === 'string' && item.arguments) c.function.arguments = item.arguments;
    }
    return c;
  };
  for (...) {
    ...
    if (o.type === 'response.output_text.delta') content += o.delta || '';
    if (o.type === 'response.output_item.added' && o.item && o.item.type === 'function_call') {
      callEntry(o.item.id != null ? o.item.id : o.output_index, o.item);
    }
    if (o.type === 'response.function_call_arguments.delta') {
      const c = callEntry(o.item_id != null ? o.item_id : o.output_index, null);
      c.function.arguments += typeof o.delta === 'string' ? o.delta : '';
    }
    if (o.type === 'response.output_item.done' && o.item && o.item.type === 'function_call') {
      callEntry(o.item.id != null ? o.item.id : o.output_index, o.item);
    }
    ...
  }
  const tool_calls = [...calls.values()];
  const out = { content, status, stopped, tool_calls };
  if (err) return { ...out, finish_reason: 'error', error: ... };
  if (incomplete) return { ...out, finish_reason: 'error', error: ... };
  if (status !== 'completed') return { ...out, finish_reason: 'error', error: ... };
  if (!content.trim() && !tool_calls.length) return { ...out, finish_reason: 'error', error: 'модель вернула пустой ответ' };
  return { ...out, finish_reason: 'stop', usage };
}
```

Careful: the previous success return didn't include `tool_calls` key; now it does (empty array) — completionJson checks `Array.isArray && length` so empty is fine. But existing test `relay.sseFoldResponses(...)` error assertions still work.

Note: for `output_item.done` with full arguments, I set arguments = item.arguments (replace) — that's right since it holds the complete JSON. But if deltas already accumulated and `done` has the same complete string, replacing is correct (no duplication).

Also the error paths now include `stopped` and `tool_calls` — the `out` includes stopped. Previously error returns had `stopped` too. Fine.

