```js
const A = await import('../js/ai.js');
globalThis.fetch = async () => ({ ok: true, status: 200, json: async () => ({ candidates: [{ content: { parts: [{ text: '{"a":null,"b":null,"c":null,"d":null}' }] }, finishReason: 'STOP' }] }) });
