+    var showReset by remember { mutableStateOf(false) }
+
+    LaunchedEffect(vm.pickRequest) {
+        if (vm.pickRequest != null) launch(vm.pickRequest!!)
+    }
+    LaunchedEffect(vm.confirmReset) { if (vm.confirmReset) showReset = true }
