-  const biling = settings.biling || 'orig';
-  const role = item.bubble && project.roles.find(r => r.id === item.bubble.roleId);
-  const mainText = item.bubble ? item.bubble.text : '';
-  const trText = item.bubble ? item.bubble.tr : '';
