-    ctx.textAlign = 'left'; ctx.textBaseline = 'top';
-    const pad = Math.max(4, ww * 0.04);
-    const lines = wrapLines(ctx, mainText, ww - pad * 2);
-    const maxLines = Math.floor((hh - pad * 2) / (ctx.measureText('М').width * 1.4));
