-function pickMime() {
-  const tries = [
-    'video/webm;codecs=vp9,opus', 'video/webm;codecs=vp8,opus',
-    'video/webm;codecs=vp9', 'video/webm',
-  ];
-  for (const t of tries) { try { if (MediaRecorder.isTypeSupported(t)) return t; } catch (e) {} }
-  return 'video/webm';
