-    const p = project.pages[0];
-    const ratio = p && p.w ? p.h / p.w : 16 / 9;
-    const h = 1080, w = Math.round(h / ratio);
-    return { w: w - (w % 2), h };
-  }
-  const [w, h] = resSpec.split('x').map(n => parseInt(n, 10));
-  return { w, h };
