-  // WAV 16bit mono
-  const pcm = new Int16Array(out.length);
-  for (let i = 0; i < out.length; i++) { const v = Math.max(-1, Math.min(1, out[i])); pcm[i] = v < 0 ? v * 0x8000 : v * 0x7fff; }
