+  for (let i = 0; i < lines.length; i += B) {
+    const batch = lines.slice(i, i + B).map((l, k) => ({ idx: i + k, text: l.text }));
+    const sys = `Ты — профессиональный переводчик манги/комиксов. Переведи реплики на язык: ${toLang}. ` +
