+  else t.push('<span class="mp-tag red">платно</span>');
+  if (mt.vision) t.push('<span class="mp-tag warn">👁 vision</span>');
+  if (mt.orchestrator) t.push('<span class="mp-tag">🎛 оркестратор</span>');
