+        const buf = new Uint8Array(ev.data);
+        if (buf.length >= 2) {
+          const hl = (buf[0] << 8) | buf[1];
+          chunks.push(buf.subarray(2 + hl + 2));
+        }
+      } else if (ev.data instanceof Blob) {
+        ev.data.arrayBuffer().then((ab) => {
+          const buf = new Uint8Array(ab); chunks.push(buf.subarray(0));
+        });
+      }
+    };
+  });
