+  'nowEdgeString формат (RFC 1123 с запятой, как у edge-tts)');
+
+ok(ssmlEscape('Привет <world> & "x"') === 'Привет &lt;world&gt; &amp; &quot;x&quot;', 'ssmlEscape');
