 /* resolveTakes — тот код, который реально крутит озвучка и интерфейс. */
 {
   let n = 0;
   const segDurs = [1, 2, 3, 4, 5];
   const lineDurs = [1.1, 2.2, 2.8, 4.1, 5.2];

   let r = resolveTakes({ lineDurs, segDurs, mode: 'order' });
