    fun trLangName(code: String): String = Defaults.TR_LANGS[code] ?: code

    private fun kx(s: String): String {
        val sb = StringBuilder(s.length + 8)
        sb.append('"')
        for (c in s) when (c) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> if (c.code < 0x20) sb.append(' ') else sb.append(c)
        }
        sb.append('"')
        return sb.toString()
    }
}

